31	export function createMarkdownExport(
32	  transformers: Array<Transformer>,
33	  shouldPreserveNewLines: boolean = false,
34	): (node?: ElementNode) => string {
35	  const byType = transformersByType(transformers);
36	  const elementTransformers = [...byType.multilineElement, ...byType.element];
37	  const isNewlineDelimited = !shouldPreserveNewLines;
38	
39	  // Export only uses text formats that are responsible for single format
40	  // e.g. it will filter out *** (bold, italic) and instead use separate ** and *
41	  const textFormatTransformers = byType.textFormat
42	    .filter((transformer) => transformer.format.length === 1)
43	    // Make sure all text transformers that contain 'code' in their format are at the end of the array. Otherwise, formatted code like
44	    // <strong><code>code</code></strong> will be exported as `**Bold Code**`, as the code format will be applied first, and the bold format
45	    // will be applied second and thus skipped entirely, as the code format will prevent any further formatting.
46	    .sort((a, b) => {
47	      return (
48	        Number(a.format.includes('code')) - Number(b.format.includes('code'))
49	      );
50	    });
51	
52	  return (node) => {
53	    const output = [];
54	    const children = (node || $getRoot()).getChildren();
55	
56	    for (let i = 0; i < children.length; i++) {
57	      const child = children[i];
58	      const result = exportTopLevelElements(
59	        child,
60	        elementTransformers,
61	        textFormatTransformers,
62	        byType.textMatch,
63	      );
64	
65	      if (result != null) {
66	        output.push(
67	          // separate consecutive group of texts with a line break: eg. ["hello", "world"] -> ["hello", "/nworld"]
68	          isNewlineDelimited &&
69	            i > 0 &&
70	            !isEmptyParagraph(child) &&
71	            !isEmptyParagraph(children[i - 1])
72	            ? '\n'.concat(result)
73	            : result,
74	        );
75	      }
76	    }
77	    // Ensure consecutive groups of texts are at least \n\n apart while each empty paragraph render as a newline.
78	    // Eg. ["hello", "", "", "hi", "\nworld"] -> "hello\n\n\nhi\n\nworld"
79	    return output.join('\n');
80	  };
81	}
